package com.xianyusmart.service.impl;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.xianyusmart.controller.dto.ItemListRespDTO;
import org.junit.jupiter.api.Test;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class ProductListStructureTest {
 private ItemListRespDTO parse(Map<String,Object> response){var service=new ItemServiceImpl();ReflectionTestUtils.setField(service,"objectMapper",new ObjectMapper());return ReflectionTestUtils.invokeMethod(service,"parseItemListResponse",response,1,20);}
 @Test void successWithoutDataOrCardListCannotProveEmpty(){for(var response:List.of(Map.<String,Object>of("ret",List.of("SUCCESS::成功")),Map.<String,Object>of("ret",List.of("SUCCESS::成功"),"data",Map.of()))){var data=parse(response);assertFalse(data.getSuccess());assertFalse(data.getStructureValidated());assertFalse(data.getTerminalPage());}}
 @Test void validEmptyNeedsExplicitPaginationEvidence(){var data=parse(Map.of("ret",List.of("SUCCESS::成功"),"data",Map.of("cardList",List.of())));assertTrue(data.getSuccess());assertTrue(data.getStructureValidated());assertFalse(data.getTerminalPage());assertEquals("NOT_PROVIDED",data.getTerminationEvidence());assertEquals("ON_SALE",data.getScope());}
 @Test void verifiedEmptyHasReliableTermination(){for(var page:List.of(Map.<String,Object>of("cardList",List.of(),"hasMore",false),Map.<String,Object>of("cardList",List.of(),"total",0))){var data=parse(Map.of("ret",List.of("SUCCESS::成功"),"data",page));assertTrue(data.getSuccess());assertTrue(data.getTerminalPage());assertNotEquals("NOT_PROVIDED",data.getTerminationEvidence());}}
 @Test void lastNonemptyPageRetainsItemsWithExplicitEnd(){var data=parse(Map.of("ret",List.of("SUCCESS::成功"),"data",Map.of("hasMore",false,"total",1,"cardList",List.of(Map.of("cardData",Map.of("detailParams",Map.of("itemId","QA-SYNC-last")))))));assertTrue(data.getTerminalPage());assertEquals(1,data.getItems().size());assertEquals("HAS_MORE_FALSE",data.getTerminationEvidence());}
 @Test void platformFailureCodesRemainDistinctAndSafe(){var codes=Map.of("FAIL_SYS_TOKEN_EXOIRED::private detail","CREDENTIAL_EXPIRED","FAIL_SYS_USER_VALIDATE::private detail","VERIFICATION_REQUIRED","FAIL_SYS_NO_PERMISSION::private detail","PLATFORM_PERMISSION_DENIED","FAIL_SYS_TRAFFIC_LIMIT::private detail","RATE_LIMITED");for(var c:codes.entrySet()){var data=parse(Map.of("ret",List.of(c.getKey())));assertFalse(data.getSuccess());assertEquals(c.getValue(),data.getErrorCode());}}
 @Test void shortNonemptyPageIsNotFullCoverage(){var data=parse(Map.of("ret",List.of("SUCCESS::成功"),"data",Map.of("cardList",List.of(Map.of("cardData",Map.of("detailParams",Map.of("itemId","QA-SYNC-item"),"title","Fixture"))))));assertTrue(data.getSuccess());assertFalse(data.getTerminalPage());assertEquals("QA-SYNC-item",data.getItems().getFirst().getId());}
 @Test void emptyWithContradictoryPaginationCannotProveEmpty(){for(var data:List.of(Map.<String,Object>of("cardList",List.of(),"hasMore",true),Map.<String,Object>of("cardList",List.of(),"total",2))){var result=parse(Map.of("ret",List.of("SUCCESS::成功"),"data",data));assertFalse(result.getSuccess());assertFalse(result.getTerminalPage());assertEquals("PAGINATION_CONFLICT",result.getErrorCode());}}
 @Test void malformedCardCannotBecomeEmptySuccess(){var data=parse(Map.of("ret",List.of("SUCCESS::成功"),"data",Map.of("cardList",List.of(Map.of("cardData",Map.of("title","no identity"))))));assertFalse(data.getSuccess());assertFalse(data.getStructureValidated());assertTrue(data.getItems().isEmpty());}
 @Test void oversizedPlatformPageCannotEscapeBoundedSyncWork(){var cards=java.util.Collections.nCopies(101,Map.of("cardData",Map.of("detailParams",Map.of("itemId","QA-SYNC-item"))));var data=parse(Map.of("ret",List.of("SUCCESS::成功"),"data",Map.of("cardList",cards)));assertFalse(data.getSuccess());assertFalse(data.getStructureValidated());assertEquals("LIST_PAGE_LIMIT_EXCEEDED",data.getErrorCode());assertTrue(data.getItems().isEmpty());}
}
